param([string]$Stage='')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$out="$root\M78ContinuationResults";$base='http://192.168.122.1:8872'
try{if($Stage -notin @('pre','post')){throw 'Explicit timing environment phase required'};$p="$out\m78-combined-v2-concave-environment-$Stage.json";if(Test-Path $p){throw 'Preserve previous timing environment receipt'};$os=Get-CimInstance Win32_OperatingSystem;$cpu=Get-CimInstance Win32_Processor;$processes=@(Get-Process|Where-Object {$_.CPU -ne $null}|ForEach-Object {@{id=$_.Id;name=$_.ProcessName;cpuSeconds=$_.CPU;workingSetBytes=$_.WorkingSet64}});@{utc=[DateTime]::UtcNow.ToString('o');stage=$Stage;freeBytes=(Get-PSDrive C).Free;freePhysicalKiB=$os.FreePhysicalMemory;freeVirtualKiB=$os.FreeVirtualMemory;cpu=@($cpu|ForEach-Object {@{name=$_.Name;cores=$_.NumberOfCores;logical=$_.NumberOfLogicalProcessors;loadPercent=$_.LoadPercentage}});processes=$processes;scope='Environment only, no process or VM configuration changes. Cumulative CPU snapshots bound background work over the interval; no instantaneous idle guarantee fabricated.'}|ConvertTo-Json -Depth 5|Set-Content $p -Encoding UTF8;Invoke-WebRequest -UseBasicParsing "$base/$([IO.Path]::GetFileName($p))" -Method Post -InFile $p|Out-Null}catch{$p="$out\m78-combined-v2-concave-environment-$Stage-error.txt";[string]$_.Exception.Message|Set-Content $p;Invoke-WebRequest -UseBasicParsing "$base/$([IO.Path]::GetFileName($p))" -Method Post -InFile $p|Out-Null;exit 1}
